#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
vector<double> baseline={0.04,0.06,0.05,0.03};
vector<double> candidate={0.03,0.05,0.07,0.02};
double mean=0,variance=0;
for(int i=0;i<int(baseline.size());i++)mean+=(baseline[i]-candidate[i])/baseline.size();
for(int i=0;i<int(baseline.size());i++)variance+=pow(baseline[i]-candidate[i]-mean,2)/(baseline.size()-1);
cout<<fixed<<setprecision(6)<<"mean improvement "<<mean<<" standard error "<<sqrt(variance/baseline.size())<<"\n";
return 0;
}

