#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
vector<double>x={1,2,3,4},y={2,3,5,8};
double mx=0,my=0,xx=0,xy=0;
for(int i=0;i<4;i++){mx+=x[i]/4;my+=y[i]/4;}
for(int i=0;i<4;i++){xx+=pow(x[i]-mx,2);xy+=(x[i]-mx)*(y[i]-my);}
double slope=xy/xx,intercept=my-slope*mx,sumResidual=0,orthogonality=0;
for(int i=0;i<4;i++){double u=y[i]-intercept-slope*x[i];sumResidual+=u;orthogonality+=x[i]*u;}
cout<<sumResidual<<" "<<orthogonality<<"\n";
return 0;
}

